module GauxPixelUpdate_FPAdd(
  input  [15:0] io_operand_0,
                io_operand_1,
  output [15:0] io_result
);

  wire [5:0]  _GEN = {1'h0, io_operand_0[14:10]};
  wire [5:0]  _GEN_0 = {1'h0, io_operand_1[14:10]};
  wire [5:0]  _expDiffAB_T_2 = _GEN - _GEN_0;
  wire [9:0]  _realA_T = _expDiffAB_T_2[5] ? io_operand_1[9:0] : io_operand_0[9:0];
  wire [5:0]  shiftAmt = _expDiffAB_T_2[5] ? _GEN_0 - _GEN : _expDiffAB_T_2;
  wire [11:0] _alignedB_T_2 =
    shiftAmt > 6'hC
      ? 12'h0
      : {1'h1, _expDiffAB_T_2[5] ? io_operand_0[9:0] : io_operand_1[9:0], 1'h0}
        >> shiftAmt;
  wire        invertFlag =
    io_operand_0[14:10] == io_operand_1[14:10] & io_operand_0[9:0] < io_operand_1[9:0];
  wire        effSub = io_operand_0[15] ^ io_operand_1[15];
  wire [12:0] _rawResult_T_6 =
    (effSub & invertFlag ? {2'h2, ~_realA_T, 1'h1} : {2'h1, _realA_T, 1'h0})
    + (effSub & ~invertFlag ? {1'h1, ~_alignedB_T_2} : {1'h0, _alignedB_T_2})
    + {12'h0, effSub};
  wire [3:0]  lzCount =
    _rawResult_T_6[12]
      ? 4'h0
      : _rawResult_T_6[11]
          ? 4'h1
          : _rawResult_T_6[10]
              ? 4'h2
              : _rawResult_T_6[9]
                  ? 4'h3
                  : _rawResult_T_6[8]
                      ? 4'h4
                      : _rawResult_T_6[7]
                          ? 4'h5
                          : _rawResult_T_6[6]
                              ? 4'h6
                              : _rawResult_T_6[5]
                                  ? 4'h7
                                  : _rawResult_T_6[4]
                                      ? 4'h8
                                      : _rawResult_T_6[3]
                                          ? 4'h9
                                          : _rawResult_T_6[2]
                                              ? 4'hA
                                              : _rawResult_T_6[1] ? 4'hB : 4'hC;
  wire [6:0]  _rawExp_T_3 =
    {2'h0, _expDiffAB_T_2[5] ? io_operand_1[14:10] : io_operand_0[14:10]} + 7'h1
    - {3'h0, lzCount};
  wire        overflow = (|_rawResult_T_6) & _rawExp_T_3[6:5] == 2'h1;
  wire        normal = ~overflow & ~(~(|_rawResult_T_6) | _rawExp_T_3[6]);
  wire [27:0] _shiftResult_T = {15'h0, _rawResult_T_6} << lzCount;
  assign io_result =
    io_operand_0 == 16'h0 | io_operand_1 == 16'h0
      ? io_operand_0 | io_operand_1
      : {_expDiffAB_T_2[5] | invertFlag ? io_operand_1[15] : io_operand_0[15],
         {5{overflow}} | (normal ? _rawExp_T_3[4:0] : 5'h0),
         normal ? _shiftResult_T[11:2] : 10'h0};
endmodule

module GauxPixelUpdate_FPAdd_1(
  input  [7:0] io_operand_0,
               io_operand_1,
  output [7:0] io_result
);

  wire [4:0]  _GEN = {1'h0, io_operand_0[6:3]};
  wire [4:0]  _GEN_0 = {1'h0, io_operand_1[6:3]};
  wire [4:0]  _expDiffAB_T_2 = _GEN - _GEN_0;
  wire [2:0]  _realA_T = _expDiffAB_T_2[4] ? io_operand_1[2:0] : io_operand_0[2:0];
  wire [4:0]  shiftAmt = _expDiffAB_T_2[4] ? _GEN_0 - _GEN : _expDiffAB_T_2;
  wire [4:0]  _alignedB_T_2 =
    shiftAmt > 5'h5
      ? 5'h0
      : {1'h1, _expDiffAB_T_2[4] ? io_operand_0[2:0] : io_operand_1[2:0], 1'h0}
        >> shiftAmt;
  wire        invertFlag =
    io_operand_0[6:3] == io_operand_1[6:3] & io_operand_0[2:0] < io_operand_1[2:0];
  wire        effSub = io_operand_0[7] ^ io_operand_1[7];
  wire [5:0]  _rawResult_T_6 =
    (effSub & invertFlag ? {2'h2, ~_realA_T, 1'h1} : {2'h1, _realA_T, 1'h0})
    + (effSub & ~invertFlag ? {1'h1, ~_alignedB_T_2} : {1'h0, _alignedB_T_2})
    + {5'h0, effSub};
  wire [2:0]  lzCount =
    _rawResult_T_6[5]
      ? 3'h0
      : _rawResult_T_6[4]
          ? 3'h1
          : _rawResult_T_6[3]
              ? 3'h2
              : _rawResult_T_6[2] ? 3'h3 : {2'h2, ~(_rawResult_T_6[1])};
  wire [5:0]  _rawExp_T_3 =
    {2'h0, _expDiffAB_T_2[4] ? io_operand_1[6:3] : io_operand_0[6:3]} + 6'h1
    - {3'h0, lzCount};
  wire        overflow = (|_rawResult_T_6) & _rawExp_T_3[5:4] == 2'h1;
  wire        normal = ~overflow & ~(~(|_rawResult_T_6) | _rawExp_T_3[5]);
  wire [12:0] _shiftResult_T = {7'h0, _rawResult_T_6} << lzCount;
  assign io_result =
    io_operand_0 == 8'h0 | io_operand_1 == 8'h0
      ? io_operand_0 | io_operand_1
      : {_expDiffAB_T_2[4] | invertFlag ? io_operand_1[7] : io_operand_0[7],
         {4{overflow}} | (normal ? _rawExp_T_3[3:0] : 4'h0),
         normal ? _shiftResult_T[4:2] : 3'h0};
endmodule

