module LutBuffer#(
    parameter int TYPE = 16'b0
)(
    input  var logic [7:0] addr_0,
    output var logic [15:0] data_0,
    input  var logic [7:0] addr_1,
    output var logic [15:0] data_1,
    input  var logic [7:0] addr_2,
    output var logic [15:0] data_2,
    input  var logic [7:0] addr_3,
    output var logic [15:0] data_3
);

generate
    if(TYPE == 0) begin
        expLuts uPesudoExpLUT(
            .addr0(addr_0),
            .data0(data_0),
            .addr1(addr_1),
            .data1(data_1),
            .addr2(addr_2),
            .data2(data_2),
            .addr3(addr_3),
            .data3(data_3)
        );
    end else begin
        alphaLuts uPesudoAlphaLUT(
            .addr0(addr_0),
            .data0(data_0),
            .addr1(addr_1),
            .data1(data_1),
            .addr2(addr_2),
            .data2(data_2),
            .addr3(addr_3),
            .data3(data_3)
        );
    end
endgenerate
endmodule

