    logic                         mem_rw_enable_b;
    logic                         mem_rw_write_b ;
    logic [ADDR_WIDTH - 1 : 0]         mem_rw_addr_b  ;
    logic [DATA_WIDTH - 1 : 0]    mem_rw_dataIn_b;
    logic [DATA_WIDTH - 1 : 0]    mem_rw_bweb_b  ;

    assign  mem_rw_clock    = clock;
    assign  mem_rw_enable_a = rw_enable_a;
    assign  mem_rw_write_a  = rw_write_a;
    assign  mem_rw_addr_a   = rw_addr_a;
    assign  mem_rw_dataIn_a = rw_dataIn_a;
    assign  mem_rw_bweb_a   = rw_bweb_a;

    assign  mem_rw_enable_b = rw_enable_b;
    assign  mem_rw_write_b  = rw_write_b;
    assign  mem_rw_addr_b   = rw_addr_b;
    assign  mem_rw_dataIn_b = rw_dataIn_b;
    assign  mem_rw_bweb_b   = rw_bweb_b;

generate
    if(DATA_WIDTH == 16 && DEPTH == 2048) begin
        TSDN12FFCLLSVTA2048X16M4W uSramMacro (
            .WTSEL(2'b01),
            .RTSEL(2'b01),
            .AA(mem_rw_addr_a),
            .DA(mem_rw_dataIn_a),
            .BWEBA(mem_rw_bweb_a),
            .WEBA(!mem_rw_write_a),
            .CEBA(!mem_rw_enable_a),
            .CLKA(mem_rw_clock),
            .AB(mem_rw_addr_b),
            .DB(mem_rw_dataIn_b),
            .BWEBB(mem_rw_bweb_b),
            .WEBB(!mem_rw_write_b),
            .CEBB(!mem_rw_enable_b),
            .CLKB(mem_rw_clock),
            .QA(rw_dataOut_a),
            .QB(rw_dataOut_b)
        );
    end else if(DATA_WIDTH == 72 && DEPTH == 2048) begin
        TSDN12FFCLLSVTA2048X72M4W uSramMacro (
            .WTSEL(2'b01),
            .RTSEL(2'b01),
            .AA(mem_rw_addr_a),
            .DA(mem_rw_dataIn_a),
            .BWEBA(mem_rw_bweb_a),
            .WEBA(!mem_rw_write_a),
            .CEBA(!mem_rw_enable_a),
            .CLKA(mem_rw_clock),
            .AB(mem_rw_addr_b),
            .DB(mem_rw_dataIn_b),
            .BWEBB(mem_rw_bweb_b),
            .WEBB(!mem_rw_write_b),
            .CEBB(!mem_rw_enable_b),
            .CLKB(mem_rw_clock),
            .QA(rw_dataOut_a),
            .QB(rw_dataOut_b)
        );
    end else if(DATA_WIDTH == 64 && DEPTH == 256) begin
        TSDN12FFCLLSVTA256X64M4W uSramMacro (
            .WTSEL(2'b01),
            .RTSEL(2'b01),
            .AA(mem_rw_addr_a),
            .DA(mem_rw_dataIn_a),
            .BWEBA(mem_rw_bweb_a),
            .WEBA(!mem_rw_write_a),
            .CEBA(!mem_rw_enable_a),
            .CLKA(mem_rw_clock),
            .AB(mem_rw_addr_b),
            .DB(mem_rw_dataIn_b),
            .BWEBB(mem_rw_bweb_b),
            .WEBB(!mem_rw_write_b),
            .CEBB(!mem_rw_enable_b),
            .CLKB(mem_rw_clock),
            .QA(rw_dataOut_a),
            .QB(rw_dataOut_b)
        );
    end else begin
        $fatal(1, "Unsupported DEPTH and DATA_WIDTH combination"); // cannot pass design compiler
    end
endgenerate

`else

    GauxPixelUpdate_SramFpgaDp #(
        .DEPTH      (DEPTH),
        .ADDR_WIDTH (ADDR_WIDTH),
        .DATA_WIDTH (DATA_WIDTH),
        .MASK_UNIT  (1'd1)
    ) uSramMacro (
        .rw0_clock  (clock),
        .rw0_enable (rw_enable_a),
        .rw0_write  (rw_write_a),
        .rw0_addr   (rw_addr_a),
        .rw0_mask   (~rw_bweb_a),
        .rw0_dataIn (rw_dataIn_a),
        .rw0_dataOut(rw_dataOut_a),
        .rw1_clock  (clock),
        .rw1_enable (rw_enable_b),
        .rw1_write  (rw_write_b),
        .rw1_addr   (rw_addr_b),
        .rw1_mask   (~rw_bweb_b),
        .rw1_dataIn (rw_dataIn_b),
        .rw1_dataOut(rw_dataOut_b)
    );

`endif

endmodule : GauxPixelUpdate_SramWrapperDp




module GauxPixelUpdate_SramFpgaDp#(
    parameter int unsigned DEPTH=32'd1024,
    parameter int unsigned DATA_WIDTH=32'd128,
    parameter int unsigned MASK_UNIT=32'd8,
    parameter int unsigned ADDR_WIDTH=32'd10,
    parameter int unsigned MASK_WIDTH=(DATA_WIDTH+MASK_UNIT-32'd1)/MASK_UNIT
)(
    input logic rw0_clock,
    input logic rw0_enable,
    input logic rw0_write,
    input logic[ADDR_WIDTH-1:0] rw0_addr,
    input logic[MASK_WIDTH-1:0] rw0_mask,
    input logic[DATA_WIDTH-1:0] rw0_dataIn,
    output logic[DATA_WIDTH-1:0] rw0_dataOut,

    input logic rw1_clock,
    input logic rw1_enable,
    input logic rw1_write,
    input logic[ADDR_WIDTH-1:0] rw1_addr,
    input logic[MASK_WIDTH-1:0] rw1_mask,
    input logic[DATA_WIDTH-1:0] rw1_dataIn,
    output logic[DATA_WIDTH-1:0] rw1_dataOut
);
    logic write_enable_0;
    logic read_enable_0;
    logic write_enable_1;
    logic read_enable_1;

    logic[DATA_WIDTH-1:0] dataOutReg_0;
    logic[DATA_WIDTH-1:0] dataOutReg_1;
    logic[DATA_WIDTH-1:0] array[DEPTH-1:0];

    assign write_enable_0 = rw0_enable && rw0_write;
    assign read_enable_0 = rw0_enable && !rw0_write;
    assign write_enable_1 = rw1_enable && rw1_write;
    assign read_enable_1 = rw1_enable && !rw1_write;

    always_ff @(posedge rw0_clock or posedge rw1_clock) begin
        // Port-0
        if (write_enable_0) begin
            for (int i = 0; i < MASK_WIDTH; i++) begin
                if (rw0_mask[i]) begin
                    array[rw0_addr][i*MASK_UNIT +: MASK_UNIT] <= rw0_dataIn[i*MASK_UNIT +: MASK_UNIT];
                end
            end
        end
        if (read_enable_0) dataOutReg_0 <= array[rw0_addr];
        
        // Port-1
        if (write_enable_1) begin
            for (int j = 0; j < MASK_WIDTH; j++) begin
                if (rw1_mask[j]) begin
                    array[rw1_addr][j*MASK_UNIT +: MASK_UNIT] <= rw1_dataIn[j*MASK_UNIT +: MASK_UNIT];
                end
            end
        end
        if (read_enable_1) dataOutReg_1 <= array[rw1_addr];
    end

    assign rw0_dataOut = dataOutReg_0;
    assign rw1_dataOut = dataOutReg_1;

endmodule: GauxPixelUpdate_SramFpgaDp

